/*
 * SPDX-License-Identifier: LGPL-2.1-or-later
 * mod: usernames and passwords generated by the keyboard itself (Bitwarden has no generator API for
 * other apps), from SecureRandom. Nothing is stored or sent anywhere.
 */
package org.fcitx.fcitx5.android.data.password

import java.security.SecureRandom

object CredentialGenerator {

    private val random = SecureRandom()

    private const val LOWER = "abcdefghijkmnopqrstuvwxyz"
    private const val UPPER = "ABCDEFGHJKLMNPQRSTUVWXYZ"
    private const val DIGITS = "23456789"
    private const val SYMBOLS = "!@#$%^&*-_=+?"

    /** [length] characters with at least one lower, upper, digit and symbol; look-alikes (l 1 O 0) left out */
    fun password(length: Int = 16): String {
        val sets = listOf(LOWER, UPPER, DIGITS, SYMBOLS)
        val all = sets.joinToString("")
        val chars = sets.map { it[random.nextInt(it.length)] }.toMutableList()
        while (chars.size < length) chars += all[random.nextInt(all.length)]
        // shuffle, so the required characters aren't always first
        for (i in chars.indices.reversed()) {
            val j = random.nextInt(i + 1)
            chars[i] = chars[j].also { chars[j] = chars[i] }
        }
        return chars.joinToString("")
    }

    private val ADJECTIVES = ("brisk calm clever cosmic crisp eager fancy gentle golden happy jolly " +
            "keen lively lucky mellow nimble noble quiet rapid shiny silent smart snowy sunny swift " +
            "tidy vivid witty bold bright cheerful").split(' ')

    private val NOUNS = ("otter panda falcon tiger maple cedar river comet pebble meadow harbor " +
            "lantern rocket pixel badger heron koala lynx orca puffin raven salmon walrus willow " +
            "breeze canyon cobalt ember glacier").split(' ')

    /** e.g. "brisk.otter42" */
    fun username(): String =
        ADJECTIVES[random.nextInt(ADJECTIVES.size)] + "." + NOUNS[random.nextInt(NOUNS.size)] +
                (10 + random.nextInt(90))
}
